require __DIR__ . '/../app/bootstrap.php';require_login();$id=(int)($_GET['material']??0);$s=db()->prepare('SELECT image_path FROM materials WHERE id=?');$s->execute([$id]);$name=$s->fetchColumn();if(!$name||!preg_match('/^[a-f0-9]{40}\.(jpg|png|webp)$/',$name)){http_response_code(404);exit('ไม่พบไฟล์');}$path=rtrim((string)cfg('upload.directory'),'\\/').DIRECTORY_SEPARATOR.$name;$real=realpath($path);$base=realpath((string)cfg('upload.directory'));if(!$real||!$base||!str_starts_with($real,$base.DIRECTORY_SEPARATOR)){http_response_code(404);exit('ไม่พบไฟล์');}$mime=(new finfo(FILEINFO_MIME_TYPE))->file($real);header('Content-Type: '.$mime);header('Content-Length: '.filesize($real));header('X-Content-Type-Options: nosniff');header('Content-Disposition: inline; filename="material-image.'.pathinfo($real,PATHINFO_EXTENSION).'"');readfile($real);
